{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C07", "C11", "C15", "C02", "C12", "C32", "C33", "C36", "C37", "C41"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C07", "C11", "C15", "C02", "C12", "C32", "C33", "C36", "C37", "C41"],
  "claims": [
    {
      "claim": "6-MNA, a methoxy-substituted arylacetic acid with a free carboxylic acid, has mean absolute oral bioavailability of approximately 35-38% in healthy subjects, and neotame, a fully ionized polar dipeptide acid, achieved at least 34.3% systemic availability after oral dosing; both support F>=20% for ionized carboxylic acid-containing molecules.",
      "card_ids": ["C07", "C11", "C15"]
    },
    {
      "claim": "Tolfenamic acid, an acidic NSAID with a free carboxylic acid, showed oral bioavailability of about 91-100% in cirrhosis patients, well above the 20% threshold.",
      "card_ids": ["C02", "C12"]
    },
    {
      "claim": "L3 oral exposure records show substantial measurable oral exposure for carboxylic acid-containing reference molecules: naproxen Cmax 61.7-65.9 µg/mL after 440-500 mg and ketoprofen Cmax 2.4-12.1 µg/mL after 50-100 mg (AUC 13.6 µg·h/mL after 50 mg with sucralfate).",
      "card_ids": ["C32", "C34", "C36", "C37", "C38", "C40"]
    },
    {
      "claim": "Lacosamide oral tablets produced Cmax values of 4.76-4.93 µg/mL after 200 mg with IV/oral ratios of 1.15-1.2, consistent with high oral bioavailability for a small polar molecule.",
      "card_ids": ["C33", "C41"]
    },
    {
      "claim": "Disopyramide capsule preparations produced mean Cmax values of 2.86-2.88 mg/L, showing measurable oral exposure for a basic reference molecule.",
      "card_ids": ["C30", "C35"]
    },
    {
      "claim": "The low-exposure L3 record (C31) involves a different reference molecule and has low transferability to the query; it does not provide affirmative F<20% evidence for the query.",
      "card_ids": ["C31"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C30", "C31", "C32", "C33", "C34", "C35", "C36", "C37", "C38", "C39", "C40", "C41"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental absolute oral bioavailability measurement for the query molecule is available in the supplied records.",
    "L3 records are oral exposure (Cmax/AUC) for reference molecules, not absolute F for the query; they inform but do not create extra gold votes.",
    "Transfer from naproxen, ketoprofen, and lacosamide is based on partial structural analogy; the query's predicted logD (-2.72) is much lower than these reference acids.",
    "The trospium low-exposure record has low transferability because the query lacks the quaternary ammonium motif responsible for trospium's poor absorption.",
    "Predicted pKa/logD may be uncertain; active transport or paracellular absorption cannot be ruled out."
  ],
  "decision_summary": "L3 oral exposure records are predominantly supportive of meaningful oral exposure for acidic/small polar reference molecules and add no affirmative F<20% evidence for the query; the closest measured analogs (6-MNA, neotame, tolfenamic acid) all show F>=34%, so the high prediction is retained/strengthened with moderate confidence."
}

